def normalize(data: list) -> list:
    return [x * 2 if isinstance(x, (int, float)) else (len(x) if isinstance(x, str) else x) for x in data]

def aggregate(data: list) -> dict:
    if not data:
        return {"count": 0, "total": 0}
    count = len(data)
    if all(isinstance(x, str) for x in data):
        total = sum(len(x) for x in data)
    elif all(isinstance(x, (int, float)) for x in data):
        total = sum(data)
    else:
        # 混合类型或其他情况，尝试计算可累加项，若失败则回退
        try:
            total = sum(data)
        except TypeError:
            total = 0
    return {"count": count, "total": total}

def report(data: list) -> str:
    normalized = normalize(data)
    stats = aggregate(normalized)
    return 'count={0} total={1}'.format(stats['count'], stats['total'])
